{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/compare-mark.json
    One cell value of ComparisonTable: yes shows a check, no a dash (both with the hidden word for screen readers), any other value is shown as text.
    Props (p): value, yes, no. -#}
{%- set v_value = (p.value ?? null) -%}
{%- set v_yes = (p.yes ?? null) -%}
{%- set v_no = (p.no ?? null) -%}
{%- if og_t(og_eq(v_value, 'yes')) %}
  {%- set c_2 -%}
    {{ include('icons/LucideIcon.html.twig', {'name': 'check', 'size': 16, 'class': 'text-foreground'}, with_context = false) }}
    {%- set c_1 -%}
      {{ og_text(v_yes) }}
    {%- endset -%}
    {{ include('compose/Inline.html.twig', {'class': 'sr-only', 'children': c_1}, with_context = false) }}
  {%- endset -%}
  {{ include('compose/Inline.html.twig', {'class': 'inline-flex items-center gap-2', 'attrs': og_attrs(['data-mark', 'yes']), 'children': c_2}, with_context = false) }}
{%- endif %}
{%- if og_t(og_eq(v_value, 'no')) %}
  {%- set c_4 -%}
    {{ include('icons/LucideIcon.html.twig', {'name': 'minus', 'size': 16}, with_context = false) }}
    {%- set c_3 -%}
      {{ og_text(v_no) }}
    {%- endset -%}
    {{ include('compose/Inline.html.twig', {'class': 'sr-only', 'children': c_3}, with_context = false) }}
  {%- endset -%}
  {{ include('compose/Inline.html.twig', {'class': 'inline-flex items-center gap-2 text-muted-foreground', 'attrs': og_attrs(['data-mark', 'no']), 'children': c_4}, with_context = false) }}
{%- endif %}
{%- if og_t(og_and([not (og_eq(v_value, 'yes')), not (og_eq(v_value, 'no'))])) %}
  {%- set c_5 -%}
    {{ og_text(v_value) }}
  {%- endset -%}
  {{ include('compose/Inline.html.twig', {'children': c_5}, with_context = false) }}
{%- endif %}
